import{_ as t,o as l,c as r,a0 as s}from"./chunks/framework.D1kl_Mnt.js";const p=JSON.parse('{"title":"본사 회계 관리","description":"","frontmatter":{},"headers":[],"relativePath":"ledger/company.md","filePath":"ledger/company.md","lastUpdated":1795628070000}'),n={name:"ledger/company.md"};function e(i,o,a,g,c,d){return l(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="본사-회계-관리" tabindex="-1">본사 회계 관리 <a class="header-anchor" href="#본사-회계-관리" aria-label="Permalink to &quot;본사 회계 관리&quot;">​</a></h1><p>본사의 법인·운영 계좌별 일일 자금 현황과 잔고 정산, 그리고 본사 입출금 거래 내역(다중 분개·관계사 연결·엑셀 일괄 등록)을 체계적으로 관리하는 화면입니다.</p><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 <strong>[본사 관리] → [본사 회계 관리] → [본사 정산 현황]</strong> 또는 **[본사 거래 내역]**을 선택하여 접속합니다.</li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/company.png</code> 경로에 등록한 후 이미지 삽입 태그를 추가해 주세요.</em></p></div><h2 id="_1-본사-정산-현황" tabindex="-1">1. 본사 정산 현황 <a class="header-anchor" href="#_1-본사-정산-현황" aria-label="Permalink to &quot;1. 본사 정산 현황&quot;">​</a></h2><p>본사 자금의 일별 계좌 잔고와 당일 입출금 흐름을 마감·검증하는 화면입니다.</p><ul><li><strong>화면 구성 탭</strong>: <ul><li><strong><code>계좌별 자금현황</code></strong>: 보유 계좌별 전일 이월 잔고, 당일 입금·출금 합계, 금일 마감 잔고를 계좌별로 집계하여 조회합니다.</li><li><strong><code>당일 입출금내역</code></strong>: 선택한 기준일자에 발생한 본사 입금 및 출금 전표 상세 내역을 확인합니다.</li><li><strong><code>월별 자금집계</code></strong>: 월 단위로 본사 자금의 기초 잔고, 수입·지출 합계, 당월 순유출입 및 기말 잔고를 한눈에 파악합니다. <ul><li><strong>기간 비교 및 누계 조회</strong>: 상단의 <strong><code>전월</code></strong> 이동 버튼과 <strong><code>기준일 누계 (MTD)</code></strong> 모드 전환을 통해 <strong>전월 동기</strong>, <strong>전월 대비 증감</strong>, <strong>당해 누계(YTD)</strong> 실적을 계정과목별로 비교 분석할 수 있습니다.</li><li><strong>계정별 상세 거래내역 조회</strong>: 집계 표에서 특정 계정과목을 클릭하면 해당 기간의 상세 거래내역 팝업이 열려 세부 입출금 전표를 즉시 확인할 수 있습니다.</li></ul></li></ul></li><li><strong>일일 잔고 정산 마감</strong>: <ul><li>실계좌 잔액과 장부 잔액을 대조 확인한 뒤 <strong><code>[당일잔고 정산확인]</code></strong> 버튼으로 정산 마감을 기록하며, 마감된 일자는 <strong><code>잔고정산 확인완료</code></strong> 상태로 표시됩니다.</li><li><strong>과거 내역 잠금 보호</strong>: 최종 정산 확인일로부터 <strong>10일이 경과</strong>한 거래 내역은 임의 수정이나 삭제가 제한되어 회계 장부의 무결성을 유지합니다.</li></ul></li></ul><h2 id="_2-본사-거래-내역" tabindex="-1">2. 본사 거래 내역 <a class="header-anchor" href="#_2-본사-거래-내역" aria-label="Permalink to &quot;2. 본사 거래 내역&quot;">​</a></h2><p>본사 법인 계좌에서 발생한 모든 입출금 전표를 등록하고 계정과목별로 분류·관리하는 화면입니다.</p><ul><li><strong>다차원 조건 필터링</strong>: <ul><li>조회 기간, 입출금 구분, 계정분류 및 계정과목, 거래계좌, <strong>관계사 / 프로젝트 연결 대상</strong>, 키워드 검색을 조합하여 거래 내역을 조회합니다.</li></ul></li><li><strong>거래 등록 및 1:N 분할 처리</strong>: <ul><li>단일 입출금 건을 여러 계정과목이나 귀속 부서·프로젝트로 나누어 입력해야 할 경우 <strong>1:N 다중 분개(분할 등록)</strong> 를 지원합니다.</li><li>필요 시 거래 항목에 연관 관계사 또는 프로젝트를 지정하여 본사와 사업지 간 자금 흐름을 명확히 구분할 수 있습니다.</li></ul></li><li><strong>엑셀 대량 등록 및 편의 기능</strong>: <ul><li>신규 거래 등록 화면 상단의 엑셀 도구를 통해 여러 건의 거래를 한 번에 입력할 수 있습니다.</li><li><strong>방법 ① IBS 템플릿 엑셀 업로드 (다수 거래 + 회계 계정 일괄 등록)</strong>: <ol><li><strong><code>[엑셀 양식 다운로드]</code></strong> 버튼으로 표준 템플릿을 내려받습니다.</li><li>양식에 맞춰 은행 거래 내역과 회계 계정(1:N 분할 포함)을 작성합니다. <em>(1회 업로드 최대 60건 / 250행 지원)</em></li><li><strong><code>[IBS 템플릿 엑셀 업로드]</code></strong> 아이콘을 클릭해 파일을 선택하면 화면에 자동으로 행이 채워지며, 내용 확인 후 저장합니다.</li></ol></li><li><strong>방법 ② 은행 원본 엑셀/CSV 바로 등록</strong>: <ul><li>국민·신한·우리·하나·기업·농협 등 주요 은행 인터넷뱅킹에서 내려받은 <strong>원본 거래내역 엑셀 또는 CSV 파일</strong>을 별도로 양식에 옮기지 않고 <strong><code>[은행 원본 엑셀/CSV 업로드]</code></strong> 버튼으로 바로 불러올 수 있습니다.</li></ul></li><li><strong>방법 ③ 개별 거래건의 회계 계정(분개)만 엑셀 업로드</strong>: <ul><li>단일 입출금 건에 1:N으로 나눌 회계 계정이 많을 때는, 해당 거래 행 우측의 <strong><code>[이 거래건의 회계 계정 엑셀 업로드]</code></strong> 아이콘을 눌러 해당 건의 분개 내역만 엑셀로 일괄 입력할 수 있습니다.</li></ul></li></ul></li><li><strong>본사 거래 계좌 관리</strong>: <ul><li><strong><code>[본사 거래 계좌 관리]</code></strong> 기능을 통해 본사 회계에 연동되는 법인 계좌 정보를 추가하거나 관리할 수 있습니다.</li></ul></li></ul><h2 id="💡-실무-관리-포인트" tabindex="-1">💡 실무 관리 포인트 <a class="header-anchor" href="#💡-실무-관리-포인트" aria-label="Permalink to &quot;💡 실무 관리 포인트&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>본사 회계와 프로젝트 회계의 구분</strong> 본사 법인 운영비·인건비·본사 자금 대여 등은 **[본사 관리] → [본사 회계 관리]**에서 처리하고, 개별 분양·개발 사업지 계좌 및 사업비 출납은 **[프로젝트 관리] → [프로젝트 회계 관리]**에서 분리 관리하십시오.</p></div>',12)])])}const m=t(n,[["render",e]]);export{p as __pageData,m as default};
